{
  "description": "The creature is shown in profile facing right, standing upright on two hind limbs. It has the body, head, and tail of a large tawny-furred feline with a thick shaggy mane around the neck and chest, and a pair of very large, outstretched feathered wings attached at the shoulder and back. The overall coloration is golden-brown and cream, with darker brown feather tips and a dark tuft at the end of the tail. The wings are spread wide to either side, and the hind legs are muscular and bent as if supporting the weight of the body.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a lion-like head in right profile with a broad muzzle, dark nose, light-colored chin and whisker area, amber eye, and short tawny fur",
      "where": "at the top front of the body, above the mane"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears with dark inner fur, typical of a lion",
      "where": "on top of the head, one clearly visible in profile and the other partially visible behind it"
    },
    {
      "part": "mane",
      "looks_like": "thick, shaggy, layered hair in golden-brown tones, longer around the neck and chest and transitioning into feather-like texture on the chest",
      "where": "encircling the neck, extending down the front of the chest and onto the upper back"
    },
    {
      "part": "legs",
      "looks_like": "two muscular hind legs covered in short tawny fur with lighter fur on the inner thigh and belly, bent at the knee and hock joints",
      "where": "under the rear of the body, supporting the creature on the ground"
    },
    {
      "part": "feet",
      "looks_like": "large feline paws with visible toe pads and short dark claws, light brown fur on top",
      "where": "at the ends of the two hind legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a long, slender, fur-covered tail with tawny fur and a darker, bushy tuft at the tip",
      "where": "extending from the rear of the body, curving down and then back along the ground to the left"
    },
    {
      "part": "wings",
      "looks_like": "two very large outstretched wings with broad, layered flight feathers, brown on the upper coverts and paler cream and gray-brown on the long primary feathers",
      "where": "attached at the upper back and shoulder area, one extending to the left rear and one to the right front, spanning wide on both sides of the body"
    },
    {
      "part": "feathers",
      "looks_like": "overlapping, pointed feathers in shades of golden-brown, dark brown, and cream with darker tips, densely covering the wings and continuing as smaller scale-like feathers over the chest and shoulder",
      "where": "covering the entire surface of both wings and the upper chest and shoulder region"
    }
  ],
  "attached_objects": [],
  "animals": ["lion", "eagle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
